package com.pocketwise.controller;
import java.util.Map; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpSession; import com.pocketwise.model.AppUser; import com.pocketwise.repository.UserRepository;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; public AuthController(UserRepository u,PasswordEncoder e){users=u;encoder=e;} private Map<String,Object> safe(AppUser u){return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole());}
@PostMapping("/register") public Map<String,Object> register(@RequestBody Map<String,String> body){String name=body.getOrDefault("name","").trim(), email=body.getOrDefault("email","").trim().toLowerCase(), pass=body.getOrDefault("password",""); if(name.isBlank()||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||pass.length()<8) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a name, valid email and password of at least 8 characters"); if(users.existsByEmailIgnoreCase(email)) throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists"); AppUser u=new AppUser();u.setName(name);u.setEmail(email);u.setPassword(encoder.encode(pass));u.setRole("USER");users.save(u);return safe(u);}
@PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,String> body,HttpServletRequest req){String email=body.getOrDefault("email","").trim().toLowerCase();AppUser u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password")); if(!encoder.matches(body.getOrDefault("password",""),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"); var auth=new UsernamePasswordAuthenticationToken(u.getEmail(),null,java.util.List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+u.getRole())));SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(auth);SecurityContextHolder.setContext(context);req.getSession(true).setAttribute("SPRING_SECURITY_CONTEXT",context);return safe(u);}
@GetMapping("/me") public Map<String,Object> me(Authentication auth){AppUser u=users.findByEmailIgnoreCase(auth.getName()).orElseThrow();return safe(u);}
@PostMapping("/logout") public ResponseEntity<Void> logout(HttpServletRequest req){HttpSession session=req.getSession(false);if(session!=null)session.invalidate();SecurityContextHolder.clearContext();return ResponseEntity.noContent().build();}}
